// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address receiver, uint256 amount) public {
        vm.assume(receiver != address(0));
        vm.assume(amount > 0);
        vm.assume(receiver != address(c)); // avoid self-transfer issues
        // fund the contract so it can transfer
        vm.deal(address(c), amount);
        // attempt the call
        (bool ok, ) = address(c).call(abi.encodeWithSignature("sendTo(address,uint256)", receiver, amount));
        assertTrue(ok == true, "sendTo should not revert when amount > 0 and owner sends");
    }
}

